dCheck,\n  Clock,\n  Tag,\n  ChevronLeft,\n  AlertCircle,\n  Settings2,\n  UserMinus,\n  ChevronDown,\n  User2,\n  Activity,\n  XCircle,\n} from \"lucide-react\";\n\nimport { fetchClient } from \"@/lib/api-client\";\nimport { Button } from \"@/components/ui/button\";\nimport { Form, FormControl, FormField, FormItem } from \"@/components/ui/form\";\nimport { Textarea } from \"@/components/ui/textarea\";\nimport { Badge } from \"@/components/ui/badge\";\nimport { ScrollArea } from \"@/components/ui/scroll-area\";\nimport { toast } from \"sonner\";\nimport { format } from \"date-fns\";\nimport Link from \"next/link\";\nimport { useAuth } from \"@/context/AuthContext\";\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuItem,\n  DropdownMenuTrigger,\n  DropdownMenuSeparator,\n  DropdownMenuLabel,\n} from \"@/components/ui/dropdown-menu\";\nimport {\n  AlertDialog,\n  AlertDialogContent,\n  AlertDialogFooter,\n  AlertDialogHeader,\n  AlertDialogTitle,\n  AlertDialogAction,\n  AlertDialogCancel,\n} from \"@/components/ui/alert-dialog\";\nimport {\n  Dialog,\n  DialogContent,\n  DialogFooter,\n  DialogHeader,\n  DialogTitle,\n} from \"@/components/ui/dialog\";\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectTrigger,\n  SelectValue,\n} from \"@/components/ui/select\";\n\nimport { Ticket, TicketMessage, TicketActions } from \"@/lib/types\";\nimport { TICKET_CATEGORIES } from \"@/entities/core/model/types\";\n\nconst messageSchema = z.object({\n  content: z.string().min(1),\n});\n\nconst categorySchema = z.object({\n  newCategory: z.string().min(1),\n});\n\nexport default function TicketDetailsPage() {\n  const { id } = useParams();\n  const router = useRouter();\n  const { user: currentUser } = useAuth();\n\n  const [ticket, setTicket] = useState<Ticket | null>(null);\n  const [isLoading, setIsLoading] = useState(true);\n  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);\n  const [isCategoryDialogOpen, setIsCategoryDialogOpen] = useState(false);\n\n  const scrollRef = useRef<HTMLDivElement>(null);\n\n  const form = useForm({\n    resolver: zodResolver(messageSchema),\n    defaultValues: { content: \"\" },\n  });\n\n  const categoryForm = useForm({\n    resolver: zodResolver(categorySchema),\n    defaultValues: { newCategory: \"\" },\n  });\n\n  // ---------------- FETCH ----------------\n\n  const fetchData = async () => {\n    try {\n      const data = (await fetchClient(\n        `/private/tickets/populate/${id}`\n      )) as Ticket;\n\n      setTicket(data);\n      categoryForm.reset({ newCategory: data.ticket.category });\n    } catch {\n      toast.error(\"Failed to load ticket\");\n    } finally {\n      setIsLoading(false);\n    }\n  };\n\n  useEffect(() => {\n    fetchData();\n  }, [id]);\n\n  // ---------------- TIMELINE ----------------\n\n  const timeline = useMemo(() => {\n    if (!ticket) return [];\n\n    const messages = ticket.messages.map((m) => ({\n      type: \"message\" as const,\n      date: new Date(m.createdAt),\n      data: m,\n    }));\n\n    const actions = ticket.actions.map((a) => ({\n      type: \"action\" as const,\n      date: new Date(a.created_at),\n      data: a,\n    }));\n\n    return [...messages, ...actions].sort(\n      (a, b) => a.date.getTime() - b.date.getTime()\n    );\n  }, [ticket]);\n\n  useEffect(() => {\n    if (scrollRef.current) {\n      const viewport = scrollRef.current.querySelector(\n        \"[data-radix-scroll-area-viewport]\"\n      );\n      if (viewport) {\n        viewport.scrollTo({\n          top: viewport.scrollHeight,\n          behavior: \"smooth\",\n        });\n      }\n    }\n  }, [timeline]);\n\n  // ---------------- SEND ----------------\n\n  async function onSendMessage(values: { content: string }) {\n    if (!ticket) return;\n\n    try {\n      const updated = (await fetchClient(\"/private/tickets/send\", {\n        method: \"POST\",\n        body: JSON.stringify({\n          ticket,\n          content: values.content,\n        }),\n      })) as Ticket;\n\n      setTicket(updated);\n      form.reset();\n    } catch {\n      toast.error(\"Message failed\");\n    }\n  }\n\n  // ---------------- CLOSE ----------------\n\n  const handleClose = async () => {\n    try {\n      const updated = (await fetchClient(\n        `/private/tickets/close/${id}`,\n        { method: \"PATCH\" }\n      )) as Ticket;\n\n      setTicket(updated);\n      toast.success(\"Ticket closed\");\n    } catch {\n      toast.error(\"Close failed\");\n    }\n  };\n\n  // ---------------- DELETE ----------------\n\n  const handleDelete = async () => {\n    try {\n      await fetchClient(`/private/tickets/delete/${id}`, {\n        method: \"DELETE\",\n      });\n\n      toast.success(\"Deleted\");\n      router.push(\"/\");\n    } catch {\n      toast.error(\"Delete failed\");\n    } finally {\n      setIsDeleteDialogOpen(false);\n    }\n  };\n\n  // ---------------- CATEGORY ----------------\n\n  const onCategorySubmit = async (values: { newCategory: string }) => {\n    try {\n      const updated = (await fetchClient(\n        `/private/admin/tickets/edit/category/${id}`,\n        {\n          method: \"PATCH\",\n          body: JSON.stringify(values),\n        }\n      )) as Ticket;\n\n      setTicket(updated);\n      toast.success(\"Category updated\");\n      setIsCategoryDialogOpen(false);\n    } catch {\n      toast.error(\"Category update failed\");\n    }\n  };\n\n  // ---------------- PERMISSIONS ----------------\n\n  if (isLoading) return <div>Loading...</div>;\n  if (!ticket) return <div>Not found</div>;\n\n  const isCurrentUserStaff = (currentUser?.staffRank ?? 0) > 0;\n  const canReply =\n    ticket.ticket.status !== \"CLOSED\" &&\n    (ticket.ticket.author.id === currentUser?.id ||\n      ticket.ticket.handler?.id === currentUser?.id);\n\n  // ---------------- RENDER ----------------\n\n  return (\n    <>\n      <motion.div className=\"flex flex-col h-[calc(100vh-120px)] max-w-5xl mx-auto w-full border rounded-xl overflow-hidden\">\n        {/* HEADER */}\n        <div className=\"p-4 border-b flex justify-between items-center\">\n          <div className=\"flex items-center gap-4\">\n            <Link href=\"/\">\n              <Button variant=\"ghost\" size=\"icon\">\n                <ChevronLeft className=\"h-5 w-5\" />\n              </Button>\n            </Link>\n\n            <div>\n              <h1 className=\"font-semibold text-lg\">\n                {ticket.ticket.title}\n              </h1>\n\n              <div className=\"flex gap-3 text-xs mt-1 text-muted-foreground\">\n                <span className=\"flex items-center gap-1\">\n                  <Tag className=\"h-3 w-3\" /> {ticket.ticket.category}\n                </span>\n\n                <span className=\"flex items-center gap-1\">\n                  <Clock className=\"h-3 w-3\" />\n                  {format(new Date(ticket.ticket.createdAt), \"dd/MM/yy HH:mm\")}\n                </span>\n              </div>\n            </div>\n          </div>\n\n          {isCurrentUserStaff && (\n            <DropdownMenu>\n              <DropdownMenuTrigger asChild>\n                <Button variant=\"secondary\" size=\"sm\">\n                  <Settings2 className=\"h-4 w-4 mr-2\" />\n                  Manage\n                  <ChevronDown className=\"h-3 w-3 ml-1\" />\n                </Button>\n              </DropdownMenuTrigger>\n\n              <DropdownMenuContent align=\"end\">\n                <DropdownMenuLabel>Ticket Management</DropdownMenuLabel>\n                <DropdownMenuSeparator />\n\n                <DropdownMenuItem\n                  onClick={() => setIsCategoryDialogOpen(true)}\n                >\n                  Change Category\n                </DropdownMenuItem>\n\n                <DropdownMenuItem\n                  onClick={() => setIsDeleteDialogOpen(true)}\n                >\n                  Delete\n                </DropdownMenuItem>\n\n                <DropdownMenuItem onClick={handleClose}>\n                  Close\n                </DropdownMenuItem>\n              </DropdownMenuContent>\n            </DropdownMenu>\n          )}\n        </div>\n\n        {/* TIMELINE */}\n        <ScrollArea className=\"flex-1 p-6\" ref={scrollRef}>\n          <div className=\"space-y-6\">\n            {timeline.map((item) => {\n              if (item.type === \"message\") {\n                const msg = item.data as TicketMessage;\n                const isMe = msg.author.id === currentUser?.id;\n\n                return (\n                  <div\n                    key={`m-${msg.id}`}\n                    className={`flex ${\n                      isMe ? \"justify-end\" : \"justify-start\"\n                    }`}\n                  >\n                    <div\n                      className={`max-w-[70%] px-4 py-3 rounded-2xl ${\n                        isMe\n                          ? \"bg-blue-600 text-white rounded-tr-none\"\n                          : \"bg-secondary rounded-tl-none\"\n                      }`}\n                    >\n                      <div className=\"text-xs opacity-70 mb-1\">\n                        {isMe ? \"You\" : msg.author.name}\n                      </div>\n\n                      <p className=\"text-sm whitespace-pre-wrap\">\n                        {msg.content}\n                      </p>\n                    </div>\n                  </div>\n                );\n              }\n\n              const action = item.data as TicketActions;\n\n              return (\n                <div key={`a-${action.id}`} className=\"flex justify-center\">\n                  <div className=\"flex items-center gap-2 text-xs bg-muted/40 px-4 py-2 rounded-full text-muted-foreground\">\n                    <Activity className=\"h-3 w-3\" />\n                    <span className=\"font-medium\">\n                      {action.author.name}\n                    </span>\n                    <span>{action.action}</span>\n                    <span>\n                      {format(new Date(action.created_at), \"HH:mm\")}\n                    </span>\n                  </div>\n                </div>\n              );\n            })}\n          </div>\n        </ScrollArea>\n\n        {/* INPUT */}\n        <div className=\"p-4 border-t\">\n          <Form {...form}>\n            <form\n              onSubmit={form.handleSubmit(onSendMessage)}\n              className=\"flex gap-2\"\n            >\n              <FormField\n                control={form.control}\n                name=\"content\"\n                render={({ field }) => (\n                  <FormItem className=\"flex-1\">\n                    <FormControl>\n                      <Textarea\n                        placeholder=\"Write a reply...\"\n                        disabled={!canReply}\n                        {...field}\n                      />\n                    </FormControl>\n                  </FormItem>\n                )}\n              />\n              <Button type=\"submit\" disabled={!canReply}>\n                <Send className=\"h-4 w-4\" />\n              </Button>\n            </form>\n          </Form>\n\n          {!canReply && (\n            <p className=\"text-xs text-red-400 mt-2 flex items-center gap-1\">\n              <AlertCircle className=\"h-3 w-3\" />\n              You cannot reply to this ticket\n            </p>\n          )}\n        </div>\n      </motion.div>\n\n      {/* DELETE DIALOG */}\n      <AlertDialog\n        open={isDeleteDialogOpen}\n        onOpenChange={setIsDeleteDialogOpen}\n      >\n        <AlertDialogContent>\n          <AlertDialogHeader>\n            <AlertDialogTitle>\n              Are you sure?\n            </AlertDialogTitle>\n          </AlertDialogHeader>\n          <AlertDialogFooter>\n            <AlertDialogCancel>Cancel</AlertDialogCancel>\n            <AlertDialogAction onClick={handleDelete}>\n              Delete\n            </AlertDialogAction>\n          </AlertDialogFooter>\n        </AlertDialogContent>\n      </AlertDialog>\n\n      {/* CATEGORY DIALOG */}\n      <Dialog\n        open={isCategoryDialogOpen}\n        onOpenChange={setIsCategoryDialogOpen}\n      >\n        <DialogContent>\n          <DialogHeader>\n            <DialogTitle>Change Category</DialogTitle>\n          </DialogHeader>\n\n          <Form {...categoryForm}>\n            <form\n              onSubmit={categoryForm.handleSubmit(onCategorySubmit)}\n              className=\"space-y-4\"\n            >\n              <FormField\n                control={categoryForm.control}\n                name=\"newCategory\"\n                render={({ field }) => (\n                  <Select\n                    onValueChange={field.onChange}\n                    defaultValue={field.value}\n                  >\n                    <SelectTrigger>\n                      <SelectValue />\n                    </SelectTrigger>\n                    <SelectContent>\n                      {TICKET_CATEGORIES.map((cat) => (\n                        <SelectItem\n                          key={cat.value}\n                          value={cat.label}\n                        >\n                          {cat.label}\n                        </SelectItem>\n                      ))}\n                    </SelectContent>\n                  </Select>\n                )}\n              />\n              <DialogFooter>\n                <Button type=\"submit\">\n                  Save\n                </Button>\n              </DialogFooter>\n            </form>\n          </Form>\n        </DialogContent>\n      </Dialog>\n    </>\n  );\n}'),(82,25,50,'2026-02-26 04:32:29','asdasd'),(83,25,50,'2026-02-27 02:14:47','asd'),(84,25,50,'2026-02-27 03:03:38','asd'),(85,25,50,'2026-02-27 03:05:12','фыв'),(86,25,50,'2026-02-27 03:05:21','фыв'),(87,25,50,'2026-02-27 03:14:47','asd'),(88,25,50,'2026-02-27 03:14:50','asdasd'),(89,25,50,'2026-02-27 03:15:43','фыв'),(90,25,50,'2026-02-27 03:20:02','asd'),(91,25,50,'2026-02-27 03:21:44','asd'),(92,26,68,'2026-02-27 03:27:05','wrfarfrfwrfwarfwaqtrfawtfaw'),(93,26,68,'2026-02-27 03:27:10','wqrfqawrfwrfwrwrf'),(94,27,68,'2026-02-27 03:27:26','rfqawsrfaftwatfgwazrff'),(95,27,50,'2026-02-27 03:56:06','asd'),(96,27,50,'2026-02-27 04:37:22','sadasd'),(97,27,50,'2026-02-27 04:37:23','asdsadsad'),(98,27,50,'2026-02-27 04:37:26','asdasd'),(99,25,50,'2026-02-27 14:32:28','фыв'),(100,28,50,'2026-03-02 03:12:55','afawrfawrfwarf'),(101,25,50,'2026-03-02 03:13:12','asd'),(102,29,50,'2026-03-02 03:18:51','ффффффффффффффффффф'),(103,29,50,'2026-03-04 16:47:24','фыв'),(104,29,50,'2026-03-04 16:47:27','фыв');
